/* ---------- 我方气泡：浅蓝方圆（#bde1fb）缩小版 + 右侧中间装饰 + 左侧外侧装饰 ---------- */
:root {
  /* 我方气泡颜色 */
  --bubble-me-bg: #bde1fb;
  --bubble-me-color: #1a1a1a;

  /* 我方气泡圆角（缩小版：保持方圆感） */
  --bubble-me-radius: 10px;
  --bubble-me-radius-first: 10px 10px 5px 10px;
  --bubble-me-radius-mid: 10px 5px 5px 10px;
  --bubble-me-radius-last: 10px 5px 10px 10px;

  /* 缩小内边距（右侧留出空间给装饰图） */
  --bubble-me-padding: 6px 6px 6px 10px;

  /* 缩小字号 */
  --bubble-me-font-size: 13px;

  /* 轻微阴影 */
  --bubble-me-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);

  /* 我方气泡内链接颜色 */
  --bubble-me-link-color: #0066cc;
}

/* ---------- 对方气泡：白色方圆（无边框）缩小版 + 左侧中间装饰 ---------- */
:root {
  /* 对方气泡颜色 */
  --bubble-them-bg: #ffffff;
  --bubble-them-color: #1f2d3d;

  /* 对方气泡圆角（缩小版） */
  --bubble-them-radius: 10px;
  --bubble-them-radius-first: 10px 10px 10px 5px;
  --bubble-them-radius-mid: 5px 10px 10px 5px;
  --bubble-them-radius-last: 5px 10px 10px 10px;

  /* 缩小内边距（左侧留出空间给装饰图） */
  --bubble-them-padding: 6px 10px 6px 6px;

  /* 缩小字号 */
  --bubble-them-font-size: 13px;

  /* 无边框 */
